                            <div className="flex items-center justify-between mb-3">
                              <span className="px-2.5 py-1 bg-indigo-50 text-indigo-600 text-[10px] font-bold uppercase rounded-md inline-block">{selectedCardData.category}</span>
                              <div className="flex items-center gap-2">
                                <div className="flex items-center bg-slate-100 rounded-lg p-0.5 mr-2">
                                  <button onClick={handlePrevCard} disabled={currentCardIndex <= 0} className="w-7 h-7 flex items-center justify-center text-slate-500 hover:text-slate-800 disabled:opacity-30 disabled:hover:text-slate-500"><i className="fa-solid fa-chevron-left text-xs"></i></button>
                                  <div className="w-px h-3 bg-slate-300 mx-0.5"></div>
                                  <button onClick={handleNextCard} disabled={currentCardIndex === -1 || currentCardIndex >= visibleCards.length - 1} className="w-7 h-7 flex items-center justify-center text-slate-500 hover:text-slate-800 disabled:opacity-30 disabled:hover:text-slate-500"><i className="fa-solid fa-chevron-right text-xs"></i></button>
                                </div>
                                <button onClick={(e) => handleDeleteCard(e, selectedCardData.id)} className="text-[10px] font-bold text-red-400 hover:text-red-600 uppercase tracking-widest flex items-center gap-1.5 px-3 py-1 hover:bg-red-50 rounded-lg transition-colors"><i className="fa-solid fa-trash-can"></i></button>
                              </div>
                            </div>
                            <h1 className="text-2xl font-extrabold text-slate-900 leading-tight mb-2 truncate">
                              {selectedCardData.prefix && <span className="text-slate-400 font-medium text-lg mr-2">{selectedCardData.prefix}</span>}
                              {selectedCardData.firstName} {selectedCardData.lastName}
