      setCropRegions(regions);
    } catch (e) { console.warn(e); } 
    finally { setIsAiDetecting(false); }
  };

  const renderPdfPage = async (pdf: any, pageNum: number) => {
    setIsRenderingPdf(true);
    try {
        const page = await pdf.getPage(pageNum);
        const scale = 2;
        const viewport = page.getViewport({ scale });
        const canvas = document.createElement('canvas');
        const context = canvas.getContext('2d');
        canvas.height = viewport.height;
        canvas.width = viewport.width;

        if (context) {
            await page.render({ canvasContext: context, viewport }).promise;
            const b64 = canvas.toDataURL('image/jpeg');
            setCropperImage(b64);
            setCropRegions([]);
            autoDetectInCropper(b64.split(',')[1]);
        }
    } catch (e) { alert("無法讀取 PDF 頁面"); } 
    finally { setIsRenderingPdf(false); }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const firstFile = files[0];
    if (firstFile.type === 'application/pdf') {
        const reader = new FileReader();
        reader.onload = async (ev) => {
            const typedarray = new Uint8Array(ev.target?.result as ArrayBuffer);
            try {
                const pdf = await pdfjs.getDocument(typedarray).promise;
                setPdfDoc(pdf);
                setCurrentPdfPage(1);
                await renderPdfPage(pdf, 1);
                setViewMode('cropper');
            } catch (err) { console.error(err); alert("PDF 解析失敗"); }
        };
        reader.readAsArrayBuffer(firstFile);
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    if (files.length === 1) {
        const reader = new FileReader();
        reader.onload = (event) => {
            const b64 = event.target?.result as string;
            setCropperImage(b64);
            setCropRegions([]);
            setViewMode('cropper');
            autoDetectInCropper(b64.split(',')[1]);
        };
        reader.readAsDataURL(firstFile);
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    const newTasks: ProcessingTask[] = [];
    for (const f of Array.from(files) as File[]) {
      const id = crypto.randomUUID();
      filesMap.current.set(id, f);
      const previewUrl = URL.createObjectURL(f);
      newTasks.push({ id, fileName: f.name, status: 'pending', progress: 0, batchIndex: 1, previewUrl });
    }
    setTasks(prev => [...prev, ...newTasks]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const getMousePos = (e: React.MouseEvent | React.TouchEvent) => {
    if (!cropperImgRef.current) return { x: 0, y: 0 };
    const rect = cropperImgRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;
    return {
      x: ((clientX - rect.left) / rect.width) * 100,
      y: ((clientY - rect.top) / rect.height) * 100
    };
  };

  const handleCropStart = (e: React.MouseEvent | React.TouchEvent, action: 'draw' | 'move' | 'resize' = 'draw', cropId?: string, handle?: string) => {
    const pos = getMousePos(e);
    setStartPos(pos);
    if (action === 'draw') {
        setCurrentRect({ id: 'temp', x: pos.x, y: pos.y, w: 0, h: 0 });
        setIsDrawing(true);
        setActiveCropId(null);
    } else if (action === 'move' && cropId) {
        const crop = cropRegions.find(r => r.id === cropId);
        if (crop) { setInitialRect({ ...crop }); setIsMoving(true); setActiveCropId(cropId); }
    } else if (action === 'resize' && cropId && handle) {
        const crop = cropRegions.find(r => r.id === cropId);
        if (crop) { setInitialRect({ ...crop }); setIsResizing(handle); setActiveCropId(cropId); }
    }
  };

  const handleCropMove = (e: React.MouseEvent | React.TouchEvent) => {
    const pos = getMousePos(e);
    if (isDrawing && currentRect) {
        setCurrentRect({ ...currentRect, x: Math.min(pos.x, startPos.x), y: Math.min(pos.y, startPos.y), w: Math.abs(pos.x - startPos.x), h: Math.abs(pos.y - startPos.y) });
    } else if (isMoving && activeCropId && initialRect) {
        setCropRegions(prev => prev.map(r => r.id === activeCropId ? { ...r, x: Math.max(0, Math.min(100 - r.w, initialRect.x + (pos.x - startPos.x))), y: Math.max(0, Math.min(100 - r.h, initialRect.y + (pos.y - startPos.y))) } : r));
    } else if (isResizing && activeCropId && initialRect) {
        const dx = pos.x - startPos.x; const dy = pos.y - startPos.y;
        setCropRegions(prev => prev.map(r => {
            if (r.id !== activeCropId) return r;
            let { x, y, w, h } = initialRect;
            if (isResizing.includes('t')) { const newY = Math.max(0, y + dy); h = h + (y - newY); y = newY; }
            if (isResizing.includes('b')) { h = Math.max(1, Math.min(100 - y, h + dy)); }
            if (isResizing.includes('l')) { const newX = Math.max(0, x + dx); w = w + (x - newX); x = newX; }
            if (isResizing.includes('r')) { w = Math.max(1, Math.min(100 - x, w + dx)); }
            return { ...r, x, y, w, h };
        }));
    }
  };

  const handleCropEnd = () => {
    if (isDrawing && currentRect && currentRect.w > 2 && currentRect.h > 2) {
        const newCrop = { ...currentRect, id: crypto.randomUUID() };
        setCropRegions(prev => [...prev, newCrop]);
        setActiveCropId(newCrop.id);
    }
    setIsDrawing(false); setIsMoving(false); setIsResizing(null); setCurrentRect(null);
  };

  const processCrops = async () => {
    if (!cropperImage || !cropperImgRef.current) return;
    const sourceImg = new Image();
    sourceImg.src = cropperImage;
    await new Promise(r => sourceImg.onload = r);
    const newTasks: ProcessingTask[] = [];
    for (let i = 0; i < cropRegions.length; i++) {
        const crop = cropRegions[i];
        const canvas = document.createElement('canvas');
        const rX = (crop.x / 100) * sourceImg.naturalWidth; const rY = (crop.y / 100) * sourceImg.naturalHeight;
        const rW = (crop.w / 100) * sourceImg.naturalWidth; const rH = (crop.h / 100) * sourceImg.naturalHeight;
        canvas.width = rW; canvas.height = rH;
        const ctx = canvas.getContext('2d');
        if (ctx) {
            ctx.drawImage(sourceImg, rX, rY, rW, rH, 0, 0, rW, rH);
            const blob = await new Promise<Blob | null>(res => canvas.toBlob(res, 'image/jpeg', 0.95));
            if (blob) {
                const id = crypto.randomUUID(); filesMap.current.set(id, blob);
                newTasks.push({ id, fileName: `CROP_${i+1}.jpg`, status: 'pending', progress: 0, batchIndex: 1, previewUrl: URL.createObjectURL(blob) });
            }
        }
    }
    setTasks(prev => [...prev, ...newTasks]); 
    setPdfDoc(null); setCropperImage(null); 
    setViewMode('file'); 
  };

  const visibleCards = useMemo(() => cards.filter(c => c.category === activeCategory), [cards, activeCategory]);
  const activeTasks = useMemo(() => tasks.filter(t => t.status === 'pending' || t.status === 'processing' || t.status === 'error'), [tasks]);

  const handleNextCard = () => {
    if (!selectedCardId || visibleCards.length <= 1) return;
    const currentIndex = visibleCards.findIndex(c => c.id === selectedCardId);
    if (currentIndex >= 0 && currentIndex < visibleCards.length - 1) {
      setSelectedCardId(visibleCards[currentIndex + 1].id);
    }
  };

  const handlePrevCard = () => {
    if (!selectedCardId || visibleCards.length <= 1) return;
    const currentIndex = visibleCards.findIndex(c => c.id === selectedCardId);
    if (currentIndex > 0) {
      setSelectedCardId(visibleCards[currentIndex - 1].id);
    }
  };

  const currentCardIndex = selectedCardId ? visibleCards.findIndex(c => c.id === selectedCardId) : -1;

  // View Logic for Mobile vs Desktop
  const showDashboard = !isMobile || viewMode === 'file';
  const showMain = !isMobile || viewMode !== 'file';

  // Fix for Android camera intent: force specific image types to skip "Camera vs File" chooser where possible
  const acceptAttribute = isMobile 
    ? "image/jpeg, image/png, image/webp" 
    : "image/jpeg, image/png, image/webp, application/pdf";

  return (
    <div className="flex h-full w-full overflow-hidden bg-[#f8fafc] text-slate-900 font-sans">
      <input type="file" ref={fileInputRef} className="hidden" accept={acceptAttribute} multiple onChange={handleFileUpload} />

      {showDashboard && (
        <aside className={`${isMobile ? 'w-full' : 'w-[320px] border-r border-slate-200'} h-full flex flex-col bg-white shadow-xl lg:shadow-none z-10`}>
           <div className="px-5 pt-6 pb-4 bg-white shrink-0 z-10 sticky top-0 border-b border-slate-100" style={{ paddingTop: 'calc(1.5rem + var(--sat))' }}>
              <div className="flex items-center justify-between mb-5">
                 <div className="flex items-center gap-3">
                    <div className="w-9 h-9 bg-gradient-to-br from-indigo-600 to-indigo-700 rounded-xl flex items-center justify-center text-white shadow-md shadow-indigo-200">
                       <i className="fa-solid fa-bahai text-base animate-[spin_10s_linear_infinite]"></i>
                    </div>
                    <div>
                       <h1 className="text-sm font-black text-slate-900 leading-none">QS HUB</h1>
                       <div className="text-[9px] font-bold text-slate-400 tracking-wider mt-0.5">SCANNER PRO</div>
                    </div>
                 </div>
                 <div className="flex items-center gap-2">
                     {window.aistudio && (
                       <button onClick={() => window.aistudio.openSelectKey()} className="w-8 h-8 rounded-full bg-slate-50 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 flex items-center justify-center transition-colors">
                          <i className="fa-solid fa-key text-xs"></i>
                       </button>
                     )}
                     <button 
                       onClick={handleClearAll} 
                       disabled={cards.length === 0}
                       className="w-8 h-8 rounded-full bg-slate-50 text-slate-400 hover:text-red-500 hover:bg-red-50 flex items-center justify-center transition-colors disabled:opacity-30"
                       title="清空紀錄"
                     >
                       <i className="fa-solid fa-trash-can text-xs"></i>
                     </button>
                 </div>
              </div>

              <div className="grid grid-cols-2 gap-3 mb-5">
                 <button onClick={() => isMobile ? setViewMode('camera') : fileInputRef.current?.click()} className="flex flex-col items-center justify-center p-3.5 bg-indigo-600 text-white rounded-xl shadow-lg shadow-indigo-200 active:scale-95 transition-transform group">
                    <i className="fa-solid fa-camera text-xl mb-1 group-hover:scale-110 transition-transform"></i>
                    <span className="text-[10px] font-bold uppercase tracking-wide">拍照掃描</span>
                 </button>
                 <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center p-3.5 bg-white border border-slate-200 text-slate-600 rounded-xl active:scale-95 transition-transform hover:bg-slate-50 hover:border-indigo-200 group">
                    <i className="fa-solid fa-cloud-arrow-up text-xl mb-1 group-hover:text-indigo-500 transition-colors"></i>
                    <span className="text-[10px] font-bold uppercase tracking-wide">匯入檔案</span>
                 </button>
              </div>

              <div className="flex p-1 bg-slate-100/80 rounded-lg mb-3">
                 <CompactTab label="Employer" active={activeCategory === 'employer'} count={cards.filter(c=>c.category==='employer').length} onClick={() => setActiveCategory('employer')} />
                 <CompactTab label="Academic" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
                 <CompactTab label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
              </div>

              <div className="flex gap-2">
                 <button onClick={() => handleShareOrExport(activeCategory, 'qs')} disabled={isExporting} className="flex-1 py-2.5 bg-emerald-50 text-emerald-700 border border-emerald-100 rounded-lg text-[10px] font-bold uppercase tracking-wide flex items-center justify-center gap-2 active:scale-95 transition-transform disabled:opacity-50">
                    {isExporting ? <i className="fa-solid fa-circle-notch fa-spin"></i> : <i className="fa-solid fa-file-excel"></i>} 分享 Excel
                 </button>
                 <button onClick={() => handleShareOrExport('all', 'full')} disabled={isExporting} className="flex-1 py-2.5 bg-white border border-slate-200 text-slate-600 rounded-lg text-[10px] font-bold uppercase tracking-wide flex items-center justify-center gap-2 active:scale-95 transition-transform disabled:opacity-50">
                    {isExporting ? <i className="fa-solid fa-circle-notch fa-spin"></i> : <i className="fa-solid fa-file-export"></i>} 分享完整
                 </button>
              </div>
           </div>

           <div className="flex-1 overflow-y-auto custom-scrollbar p-2 bg-slate-50/50 pb-20 lg:pb-3 flex flex-col">
              {activeTasks.length > 0 && (
                <div className="mb-2 px-1 shrink-0 max-h-[150px] overflow-y-auto custom-scrollbar border-b border-slate-200 pb-2">
                  <div className="flex items-center justify-between px-1 mb-1.5">
                    <div className="text-[9px] font-bold text-indigo-500 uppercase tracking-widest flex items-center">
                       <i className={`fa-solid fa-circle-notch ${isProcessing && !isQueuePaused ? 'fa-spin' : ''} mr-1`}></i> 
                       處理佇列 ({activeTasks.length})
                    </div>
                    <button 
                       onClick={() => setIsQueuePaused(!isQueuePaused)}
                       className={`w-5 h-5 rounded flex items-center justify-center transition-colors ${isQueuePaused ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-200 text-slate-500 hover:bg-slate-300'}`}
                    >
                       <i className={`fa-solid ${isQueuePaused ? 'fa-play' : 'fa-pause'} text-[9px]`}></i>
                    </button>
                  </div>
                  {activeTasks.map(task => (
                     <div key={task.id} className="bg-white p-1.5 rounded-lg border border-indigo-100 shadow-sm flex items-center gap-2 relative overflow-hidden mb-1.5">
                         {task.status === 'processing' && !isQueuePaused && <div className="absolute bottom-0 left-0 h-0.5 bg-indigo-500 animate-[loading_1s_ease-in-out_infinite]" style={{width: '100%'}}></div>}
                         <div className="w-8 h-8 shrink-0 bg-slate-100 rounded flex items-center justify-center overflow-hidden border border-slate-200">
                            {task.previewUrl ? <img src={task.previewUrl} className="w-full h-full object-cover opacity-90" /> : <i className="fa-solid fa-file text-slate-400 text-xs"></i>}
                         </div>
                         <div className="flex-1 min-w-0">
                            <div className="text-[9px] font-bold text-slate-700 truncate">{task.fileName}</div>
                            <div className="text-[8px] text-slate-400 font-medium truncate">
                              {task.status === 'pending' && (isQueuePaused ? '已暫停' : '等待中...')}
                              {task.status === 'processing' && <span className="text-indigo-500">AI 分析中...</span>}
                              {task.status === 'error' && <span className="text-red-500">{task.error || '失敗'}</span>}
                            </div>
                         </div>
                         {task.status === 'error' && (
                           <button onClick={(e) => {e.stopPropagation(); setTasks(prev => prev.filter(t => t.id !== task.id))}} className="w-5 h-5 flex items-center justify-center text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-full"><i className="fa-solid fa-xmark text-[10px]"></i></button>
                         )}
                     </div>
                  ))}
                </div>
              )}

              <div className="grid grid-cols-2 lg:grid-cols-1 gap-2 pb-10 px-1 content-start">
                {visibleCards.length === 0 ? (
                   <div className="col-span-2 lg:col-span-1 flex flex-col items-center justify-center py-16 text-slate-300">
                     <i className="fa-regular fa-folder-open text-4xl mb-3 opacity-30"></i>
                     <span className="text-xs font-medium">尚無資料</span>
                     <p className="text-[10px] mt-1 opacity-60">請點擊上方按鈕開始掃描</p>
                   </div>
                ) : (
                   visibleCards.map(c => (
                     <div key={c.id} onClick={() => { setSelectedCardId(c.id); setViewMode('detail'); }} className={`group relative p-3 rounded-xl cursor-pointer transition-all duration-200 border flex flex-col items-center text-center gap-2 active:scale-[0.98] ${selectedCardId === c.id && !isMobile ? 'bg-white border-indigo-500 shadow-lg shadow-indigo-100' : 'bg-white border-slate-200/60 hover:border-slate-300 shadow-sm'}`}>
                       <button 
                         onClick={(e) => handleDeleteCard(e, c.id)}
                         className="absolute top-2 right-2 w-6 h-6 bg-red-50 text-red-500 rounded-full opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center hover:bg-red-500 hover:text-white"
                       >
                         <i className="fa-solid fa-trash-can text-[10px]"></i>
                       </button>
                       <div className="w-10 h-10 rounded-full bg-slate-100 text-slate-500 flex items-center justify-center text-sm font-bold shrink-0">{c.lastName.charAt(0)}{c.firstName.charAt(0)}</div>
                       <div className="w-full min-w-0">
                         <div className="font-bold text-[13px] mb-0.5 tracking-tight truncate text-slate-800">{c.firstName} {c.lastName}</div>
                         <div className="text-[10px] font-medium text-slate-400 truncate uppercase tracking-wide">{c.company}</div>
                       </div>
                     </div>
                  ))
                )}
              </div>
           </div>
        </aside>
      )}

      {showMain && (
        <main 
          className="flex-1 flex flex-col min-w-0 bg-slate-50 relative h-full overflow-hidden" 
          style={{ 
            paddingTop: (isMobile && viewMode !== 'camera') ? 'env(safe-area-inset-top)' : 0 
          }}
        >
          <div className="flex-1 relative overflow-hidden">
            {viewMode === 'camera' && (
              <div className={`h-full ${isMobile ? '' : 'p-4 lg:p-8'} animate-fadeIn relative flex flex-col`}>
                <CameraScanner 
                   isMobile={isMobile}
                   onCapture={async (b64) => { 
                    const id = crypto.randomUUID(); const res = await fetch(`data:image/jpeg;base64,${b64}`);
                    const blob = await res.blob(); filesMap.current.set(id, blob);
                    const previewUrl = URL.createObjectURL(blob);
                    setTasks(prev => [...prev, { id, fileName: `SCAN_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1, previewUrl }]);
                    setViewMode('file'); 
                   }} 
                   onClose={() => setViewMode('file')} 
                />
              </div>
            )}

            {viewMode === 'file' && !isMobile && !selectedCardData && !cropperImage && (
              <div className="h-full flex flex-col items-center justify-center p-4 lg:p-10 animate-fadeInUp relative">
                <div className="w-full max-w-2xl p-8 lg:p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] bg-white/80 backdrop-blur-lg text-center group shadow-lg cursor-pointer transition-all hover:border-indigo-300 relative overflow-hidden" onClick={() => fileInputRef.current?.click()}>
                      <div className="w-20 h-20 lg:w-24 lg:h-24 bg-gradient-to-br from-indigo-500 to-indigo-700 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-xl shadow-indigo-100 relative z-10 animate-float"><i className="fa-solid fa-print text-3xl text-white"></i></div>
                      <div className="relative z-10">
                          <h3 className="text-2xl lg:text-3xl font-extrabold text-slate-800 mb-3">匯入掃描檔案</h3>
                          <p className="text-slate-400 text-sm mb-10 max-w-sm mx-auto">支援 PDF, JPG, PNG 格式<br/><span className="text-indigo-500 font-bold"><i className="fa-solid fa-wand-magic-sparkles"></i> AI 自動定位名片位置</span></p>
                          <div className="inline-flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl text-sm font-bold uppercase tracking-widest shadow-lg group-hover:bg-indigo-700 transition-all">選擇檔案</div>
                      </div>
                </div>
              </div>
            )}

            {viewMode === 'cropper' && cropperImage && (
               <div className="h-full flex flex-col bg-slate-100 animate-fadeIn" onMouseMove={handleCropMove} onMouseUp={handleCropEnd} onTouchMove={handleCropMove} onTouchEnd={handleCropEnd}>
                  <div className="flex items-center justify-between p-4 bg-white border-b border-slate-200 shrink-0 z-[100]">
                      <div className="flex items-center gap-4">
                          <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center"><i className="fa-solid fa-crop-simple"></i></div>
                          <div className="hidden lg:block">
                              <h2 className="text-[15px] font-bold text-slate-800">智慧裁切工具</h2>
                              <p className="text-[10px] font-bold uppercase tracking-wider text-slate-400">已自動定位 {cropRegions.length} 張名片</p>
                          </div>
                      </div>
                      <div className="flex gap-2">
                          {isAiDetecting && <div className="flex items-center gap-2 px-3 py-1.5 bg-indigo-50 text-indigo-600 rounded-lg animate-pulse"><i className="fa-solid fa-wand-magic-sparkles fa-spin text-xs"></i><span className="text-[10px] font-bold uppercase hidden sm:inline">AI 偵測中...</span></div>}
                          {pdfDoc && (
                              <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1">
                                  <button disabled={currentPdfPage <= 1} onClick={() => { setCurrentPdfPage(p => p - 1); renderPdfPage(pdfDoc, currentPdfPage - 1); }} className="w-8 h-8 flex items-center justify-center rounded bg-white disabled:opacity-50"><i className="fa-solid fa-chevron-left text-xs"></i></button>
                                  <span className="text-xs font-bold w-12 text-center">{currentPdfPage}/{pdfDoc.numPages}</span>
                                  <button disabled={currentPdfPage >= pdfDoc.numPages} onClick={() => { setCurrentPdfPage(p => p + 1); renderPdfPage(pdfDoc, currentPdfPage + 1); }} className="w-8 h-8 flex items-center justify-center rounded bg-white disabled:opacity-50"><i className="fa-solid fa-chevron-right text-xs"></i></button>
                              </div>
                          )}
                          <button onClick={() => { setViewMode('file'); setCropperImage(null); setPdfDoc(null); }} className="px-4 py-2 text-xs font-bold text-slate-500 hover:bg-slate-100 rounded-lg">取消</button>
                          <button onClick={processCrops} disabled={cropRegions.length === 0} className="px-6 py-2 text-xs font-bold text-white bg-indigo-600 rounded-lg shadow-lg disabled:opacity-50 flex items-center gap-2">分析 <span className="hidden sm:inline">({cropRegions.length})</span></button>
                      </div>
                  </div>
                  <div className="flex-1 overflow-auto p-4 lg:p-12 flex items-start justify-center relative select-none bg-slate-200/50" onMouseDown={(e) => { if (e.target === e.currentTarget) handleCropStart(e, 'draw'); }}>
                      <div className="relative shadow-2xl bg-white">
                          {isRenderingPdf && <div className="absolute inset-0 bg-white/80 z-[60] flex items-center justify-center backdrop-blur-sm animate-fadeIn"><i className="fa-solid fa-circle-notch fa-spin text-3xl text-indigo-500"></i></div>}
                          <img ref={cropperImgRef} src={cropperImage} className="max-w-none w-auto h-auto block select-none pointer-events-none" style={{ maxHeight: 'calc(100vh - 180px)' }} draggable={false} />
                          <div className="absolute inset-0 z-10" onMouseDown={(e) => handleCropStart(e, 'draw')}></div>
