const Field = React.memo(({ label, value, translation, icon, className }: any) => {
  const [copied, setCopied] = useState(false);
  const displayValue = value || 'N/A';
  const hasValue = Boolean(value && value.trim().length > 0);

  const handleCopy = () => {
      if (!hasValue) return;
      navigator.clipboard.writeText(value);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className={`group ${className}`}>
        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 flex items-center gap-1.5">
            {icon && <i className={`fa-solid ${icon} text-indigo-300`}></i>} {label}
        </label>
        <div className="relative">
            <div onClick={handleCopy} className={`w-full p-3 bg-white border rounded-xl text-sm font-medium transition-all cursor-pointer flex items-center justify-between group-hover:border-indigo-300 group-hover:shadow-sm ${hasValue ? 'text-slate-800 border-slate-200' : 'text-slate-300 border-slate-100 bg-slate-50 italic'}`}>
                <span className="truncate pr-8">{displayValue}</span>
                {hasValue && (
                    <span className={`absolute right-3 text-[10px] font-bold uppercase transition-all ${copied ? 'text-emerald-500' : 'text-indigo-400 opacity-0 group-hover:opacity-100'}`}>
                        {copied ? 'Copied' : 'Copy'}
                    </span>
                )}
            </div>
            {hasValue && translation && translation !== value && (
                <div className="mt-1.5 text-xs text-slate-500 font-medium px-1">
                    <span className="bg-slate-100 px-1.5 py-0.5 rounded text-[10px] text-slate-400 mr-1.5">譯</span>
                    {translation}
                </div>
            )}
        </div>
    </div>
  );
});

