const PanZoomImage = ({ src }: { src: string }) => {
    const [transform, setTransform] = useState({ scale: 1, x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);
    const dragStart = useRef({ x: 0, y: 0 });

    const handleWheel = (e: React.WheelEvent) => {
        e.preventDefault();
        const scaleChange = -e.deltaY * 0.001;
        setTransform(prev => ({
            ...prev,
            scale: Math.min(Math.max(0.5, prev.scale + scaleChange), 5)
        }));
    };

    const handleMouseDown = (e: React.MouseEvent) => {
        setIsDragging(true);
        dragStart.current = { x: e.clientX - transform.x, y: e.clientY - transform.y };
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        if (!isDragging) return;
        e.preventDefault();
        setTransform(prev => ({
            ...prev,
            x: e.clientX - dragStart.current.x,
            y: e.clientY - dragStart.current.y
        }));
    };

    const handleMouseUp = () => setIsDragging(false);

    return (
        <div className="w-full h-full relative overflow-hidden bg-slate-900 cursor-move"
             ref={containerRef}
             onWheel={handleWheel}
             onMouseDown={handleMouseDown}
             onMouseMove={handleMouseMove}
             onMouseUp={handleMouseUp}
             onMouseLeave={handleMouseUp}
        >
            <div className="absolute top-4 right-4 z-10 flex flex-col gap-2">
                <button onClick={() => setTransform(t => ({...t, scale: t.scale + 0.2}))} className="w-8 h-8 bg-black/50 text-white rounded hover:bg-black/70 flex items-center justify-center"><i className="fa-solid fa-plus"></i></button>
                <button onClick={() => setTransform(t => ({...t, scale: Math.max(0.5, t.scale - 0.2)}))} className="w-8 h-8 bg-black/50 text-white rounded hover:bg-black/70 flex items-center justify-center"><i className="fa-solid fa-minus"></i></button>
                <button onClick={() => setTransform({scale: 1, x: 0, y: 0})} className="w-8 h-8 bg-indigo-600 text-white rounded hover:bg-indigo-500 flex items-center justify-center text-xs">Reset</button>
            </div>
            <div className="w-full h-full flex items-center justify-center">
                <img 
                    src={src} 
                    className="max-w-[90%] max-h-[90%] object-contain transition-transform duration-75 ease-out shadow-2xl"
                    style={{ transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale})` }}
                    draggable={false}
                />
            </div>
            <div className="absolute bottom-4 left-4 bg-black/50 px-3 py-1 rounded text-white text-xs pointer-events-none backdrop-blur">
                滾輪縮放 · 拖曳移動
            </div>
        </div>
    );
};

