const PanZoomImage = ({ src }: { src: string }) => {
    const [transform, setTransform] = useState({ scale: 1, x: 0, y: 0, rotation: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);
    const dragStart = useRef({ x: 0, y: 0 });

    const handleWheel = (e: React.WheelEvent) => {
        e.preventDefault();
        const scaleChange = -e.deltaY * 0.001;
        setTransform(prev => ({
            ...prev,
            scale: Math.min(Math.max(0.5, prev.scale + scaleChange), 5)
        }));
    };

    const handleMouseDown = (e: React.MouseEvent) => {
        setIsDragging(true);
        dragStart.current = { x: e.clientX - transform.x, y: e.clientY - transform.y };
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        if (!isDragging) return;
        e.preventDefault();
        setTransform(prev => ({
            ...prev,
            x: e.clientX - dragStart.current.x,
            y: e.clientY - dragStart.current.y
        }));
    };

    const handleMouseUp = () => setIsDragging(false);

    const rotate = (deg: number) => {
        setTransform(prev => ({ ...prev, rotation: prev.rotation + deg }));
    };

    return (
        <div className="w-full h-full relative overflow-hidden bg-slate-900 cursor-move"
             ref={containerRef}
             onWheel={handleWheel}
             onMouseDown={handleMouseDown}
             onMouseMove={handleMouseMove}
             onMouseUp={handleMouseUp}
             onMouseLeave={handleMouseUp}
        >
            <div className="absolute top-4 right-4 z-10 flex flex-col gap-2">
                <button onClick={() => setTransform(t => ({...t, scale: t.scale + 0.2}))} className="w-8 h-8 bg-black/50 text-white rounded hover:bg-black/70 flex items-center justify-center" title="放大"><i className="fa-solid fa-plus"></i></button>
                <button onClick={() => setTransform(t => ({...t, scale: Math.max(0.5, t.scale - 0.2)}))} className="w-8 h-8 bg-black/50 text-white rounded hover:bg-black/70 flex items-center justify-center" title="縮小"><i className="fa-solid fa-minus"></i></button>
                <div className="h-px bg-white/20 my-1"></div>
                <button onClick={() => rotate(-90)} className="w-8 h-8 bg-black/50 text-white rounded hover:bg-black/70 flex items-center justify-center" title="向左旋轉"><i className="fa-solid fa-rotate-left"></i></button>
                <button onClick={() => rotate(90)} className="w-8 h-8 bg-black/50 text-white rounded hover:bg-black/70 flex items-center justify-center" title="向右旋轉"><i className="fa-solid fa-rotate-right"></i></button>
                <div className="h-px bg-white/20 my-1"></div>
                <button onClick={() => setTransform({scale: 1, x: 0, y: 0, rotation: 0})} className="w-8 h-8 bg-indigo-600 text-white rounded hover:bg-indigo-500 flex items-center justify-center text-xs" title="重置">R</button>
