                <img 
                    src={src} 
                    className="max-w-[90%] max-h-[90%] object-contain transition-transform duration-300 ease-out shadow-2xl origin-center"
                    style={{ 
                        transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale}) rotate(${transform.rotation}deg)` 
                    }}
                    draggable={false}
                />
            </div>
        </div>
    );
};

