import { GoogleGenAI, Type } from "@google/genai";

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const cleanJsonText = (text: string): string => {
  text = text.trim();
  if (text.startsWith('```json')) {
    text = text.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  } else if (text.startsWith('```')) {
    text = text.replace(/^```\s*/, '').replace(/\s*```$/, '');
  }
  return text;
};

/**
 * 提取名片詳細資料 - 使用 Flash 模型以確保極速與精準度
 */
export const extractCardInfo = async (
  base64Image: string, 
  mimeType: string = 'image/jpeg', 
  retryCount = 0
): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: `你是一位專業的名片資料分析專家，專門為 QS Hub 系統處理全球名片。

【嚴格規則】：
1. **絕對忠於原圖**：僅提取名片上「肉眼可見」的文字資訊。若名片上沒有該資訊（如電話、地址），請留空，嚴禁自行推測、搜尋或產生不存在的內容。
2. **語言處理**：若名片為雙語，對應欄位請「優先提取英文」。若無英文，則提取原文。
3. **翻譯欄位**：針對「職稱、公司、部門、產業、國家、學科」，請在 translations 物件中提供精準的中文（繁體）翻譯。
4. **稱謂 (prefix)**：僅提取名片上明確印出的稱謂 (如 Mr., Ms., Dr., Prof.)。若無，回傳空字串。

【多重資料提取規則】：
- **電話 (Phone)**：請提取名片上「所有」可見的電話號碼（包含手機、公司電話等），若有多組號碼，請用 " / " 分隔串接在同一個字串中。
- **電子郵件 (Email)**：請提取名片上「所有」可見的電子郵件，若有多組信箱，請用 " / " 分隔串接在同一個字串中。

【AI 摘要 (Reasoning) 規則】：
請用繁體中文撰寫摘要，內容必須包含以下兩點：
1. **人物識別與稱謂建議**：簡介此人是誰（職位/單位）。若名片上沒有 Prefix (稱謂)，請根據其職位或學歷給出建議 (例如：若是教授建議 Prof.，若是經理建議 Mr./Ms.)。
2. **分類依據**：說明為什麼將其歸類為 Academic、Employer 或 Staff。

請以 JSON 格式回傳。`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prefix: { type: Type.STRING },
            firstName: { type: Type.STRING },
            lastName: { type: Type.STRING },
            title: { type: Type.STRING },
            company: { type: Type.STRING },
            department: { type: Type.STRING },
            industry: { type: Type.STRING },
            country: { type: Type.STRING },
            email: { type: Type.STRING },
            subject: { type: Type.STRING },
            phone: { type: Type.STRING },
            website: { type: Type.STRING },
            address: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["employer", "academic", "staff"] },
            reasoning: { type: Type.STRING },
            translations: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                company: { type: Type.STRING },
                department: { type: Type.STRING },
                industry: { type: Type.STRING },
                subject: { type: Type.STRING },
                country: { type: Type.STRING }
              }
            }
          },
          required: ["firstName", "lastName", "title", "company", "category", "reasoning", "translations"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("AI 回應為空");
    return JSON.parse(cleanJsonText(text));

  } catch (error: any) {
    let errorMessage = error?.message || "";
    // If message is empty, try to stringify the whole error object to catch codes like 500
    if (!errorMessage) {
        try {
            errorMessage = JSON.stringify(error);
        } catch (e) {
            errorMessage = "Unknown Error";
        }
    }

    if (errorMessage.includes("Requested entity was not found")) {
        throw new Error("API_KEY_INVALID");
    }

    // Retry on 503 (Service Unavailable), 429 (Rate Limit), or 500 (Internal Server Error)
    if (
        (errorMessage.includes("503") || 
         errorMessage.includes("rate limit") || 
         errorMessage.includes("429") || 
         errorMessage.includes("500") || 
         errorMessage.includes("Internal Server Error")) && 
        retryCount < 3 // Increased retry count to 3
    ) {
      console.warn(`Gemini API Error (Attempt ${retryCount + 1}):`, errorMessage);
      await sleep(2000 * (retryCount + 1));
      return extractCardInfo(base64Image, mimeType, retryCount + 1);
    }
    throw error;
  }
};

/**
 * AI 自動偵測定位
 */
export const detectBusinessCards = async (base64Image: string, mimeType: string = 'image/jpeg'): Promise<{ymin: number, xmin: number, ymax: number, xmax: number}[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', 
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: "Detect all business cards in this image. Return their bounding boxes as a JSON array of [ymin, xmin, ymax, xmax] in normalized coordinates (0-1000).",
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            boxes: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  ymin: { type: Type.NUMBER },
                  xmin: { type: Type.NUMBER },
                  ymax: { type: Type.NUMBER },
                  xmax: { type: Type.NUMBER },
                },
                required: ["ymin", "xmin", "ymax", "xmax"]
              }
            }
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];
    const data = JSON.parse(cleanJsonText(text));
    return data.boxes || [];
  } catch (e) {
    console.warn("AI Detection failed:", e);
    return [];
  }
};

import { BusinessCardData } from '../types';

export type ExportMode = 'employer' | 'academic' | 'staff' | 'all_original' | 'all_clean' | 'single' | 'full_backup' | 'json';

// Helper: split string by common separators
const splitValues = (str: string): string[] => {
    if (!str) return [];
    return str.split(/[\/\n,;]+/).map(s => s.trim()).filter(Boolean);
};

// Logic: Pick the first phone number available
const selectSinglePhone = (phoneStr: string): string => {
    const phones = splitValues(phoneStr);
    return phones.length > 0 ? phones[0] : '';
};

// Logic: Pick email based on category
const selectBestEmail = (emailStr: string, category: string): string => {
    const emails = splitValues(emailStr);
    if (emails.length === 0) return '';
    if (emails.length === 1) return emails[0];

    const eduEmail = emails.find(e => e.toLowerCase().includes('.edu'));
    const nonEduEmail = emails.find(e => !e.toLowerCase().includes('.edu'));

    if (category === 'academic') {
        // For academic, prefer .edu
        return eduEmail || emails[0];
    } else {
        // For employer/staff, prefer non .edu (business email)
        return nonEduEmail || emails[0];
    }
};

export const createExcelFile = async (dataToExport: BusinessCardData[], mode: ExportMode): Promise<File> => {
    const XLSX = await import('xlsx');
    let exportData: any[] = [];

    // Helper to format date
    const formatDate = (ts: number) => new Date(ts).toLocaleString();

    // Map data based on Mode
    if (mode === 'single') {
        exportData = dataToExport.map(c => ({
            'First Name': c.firstName, 'Last Name': c.lastName, 'Title': c.title, 'Title (Trans)': c.translations?.title || '',
            'Company': c.company, 'Company (Trans)': c.translations?.company || '', 'Department': c.department, 'Department (Trans)': c.translations?.department || '',
            'Industry': c.industry, 'Email': c.email, 'Phone': c.phone, 'Website': c.website, 'Address': c.address, 'Country': c.country,
            'Subject': c.subject, 'Category': c.category, 'Reasoning': c.reasoning, 'Notes': c.notes || '', 'Scan Date': formatDate(c.scannedAt), 'Source': c.source
        }));
    } else if (mode === 'full_backup') {
        // Full Backup includes Image Base64 for restoration and ALL data
        exportData = dataToExport.map(c => ({
            'SYSTEM_ID': c.id, 'scannedAt': c.scannedAt, 'category': c.category, 'source': c.source,
            'firstName': c.firstName, 'lastName': c.lastName, 'prefix': c.prefix, 'title': c.title, 'company': c.company,
            'department': c.department, 'industry': c.industry, 'country': c.country, 
            'email': c.email, // Keep original full string
            'phone': c.phone, // Keep original full string
            'subject': c.subject, 'website': c.website, 'address': c.address, 'reasoning': c.reasoning,
            'notes': c.notes || '',
            'trans_title': c.translations?.title || '', 'trans_company': c.translations?.company || '', 'trans_dept': c.translations?.department || '',
            'trans_ind': c.translations?.industry || '', 'trans_subj': c.translations?.subject || '', 'trans_ctry': c.translations?.country || '',
            'IMAGE_BASE64': c.imageUrl 
        }));
    } else if (mode === 'all_clean') {
        exportData = dataToExport.map(c => ({
            'Category': c.category, 'First Name': c.firstName, 'Last Name': c.lastName, 'Title': c.title, 'Company': c.company,
            'Department': c.department, 'Industry': c.industry, 'Subject': c.subject, 'Email': c.email, 'Phone': c.phone,
            'Website': c.website, 'Address': c.address, 'Country': c.country, 'Notes': c.notes || '', 'Scan Date': formatDate(c.scannedAt)
        }));
    } else if (mode === 'all_original') {
        exportData = dataToExport.map(c => ({
             'Category': c.category, 'First Name': c.firstName, 'Last Name': c.lastName,
             'Title (Original)': c.title, 'Title (Note)': c.translations?.title || '',
             'Company (Original)': c.company, 'Company (Note)': c.translations?.company || '',
             'Department (Original)': c.department, 'Department (Note)': c.translations?.department || '',
             'Industry': c.industry, 'Industry (Note)': c.translations?.industry || '',
             'Email': c.email, 'Phone': c.phone, 'Address': c.address, 'Reasoning': c.reasoning, 'Notes': c.notes || ''
        }));
    } else if (mode === 'academic') {
        // STRICT QS ACADEMIC FORMAT (Filtered)
        exportData = dataToExport.map(c => ({
            'Source': c.source || 'QS Hub Scanner',
            'Title': c.prefix || '',
            'First Name': c.firstName || '',
            'Last Name': c.lastName || '',
            'Job Title': c.title || '',
            'Department': c.department || '',
            'Institution': c.company || '',
            'Country or Territory': c.country || '',
            'Email': selectBestEmail(c.email, 'academic'), // Logic: Prefer .edu
            'Subject': c.subject || '',
            'Phone (Optional)': selectSinglePhone(c.phone) // Logic: Pick first
        }));
    } else {
        // STRICT QS EMPLOYER / STAFF FORMAT (Filtered)
        exportData = dataToExport.map(c => ({
            'Source': c.source || 'QS Hub Scanner',
            'Title': c.prefix || '',
            'First Name': c.firstName || '',
            'Last Name': c.lastName || '',
            'Position': c.title || '',
            'Industry': c.industry || '',
            'Company Name': c.company || '',
            'Country or Territory': c.country || '',
            'Email': selectBestEmail(c.email, c.category), // Logic: Prefer non .edu
            'Phone (Optional)': selectSinglePhone(c.phone) // Logic: Pick first
        }));
    }

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "QS_Export");
    const excelBuffer = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
    const blob = new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const name = mode === 'full_backup' ? `QS_BACKUP_FULL_${new Date().toISOString().split('T')[0]}.xlsx` : `QS_Export_${mode}_${new Date().toISOString().split('T')[0]}.xlsx`;
    return new File([blob], name, { type: blob.type });
};

export const parseExcelImport = async (file: File): Promise<any[]> => {
    const XLSX = await import('xlsx');
    const ab = await file.arrayBuffer();
    const wb = XLSX.read(ab);
    const ws = wb.Sheets[wb.SheetNames[0]];
    return XLSX.utils.sheet_to_json(ws);
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
