                                    <div className="absolute top-0 left-0 bg-indigo-600 text-white text-[9px] px-1 font-bold">#{idx+1}</div>
                                    <button className="absolute -top-2 -right-2 w-5 h-5 bg-red-500 text-white rounded-full flex items-center justify-center shadow" onClick={(e)=>{e.stopPropagation();setCropRegions(p=>p.filter(r=>r.id!==crop.id))}}><i className="fa-solid fa-times text-[10px]"></i></button>
                                </div>
                            ))}
                            {isDrawing && currentRect && <div className="absolute border-2 border-dashed border-indigo-500 bg-indigo-500/10 z-30 pointer-events-none" style={{left:`${currentRect.x}%`, top:`${currentRect.y}%`, width:`${currentRect.w}%`, height:`${currentRect.h}%`}}></div>}
